const nav=(view,replace=false,extra={})=>{const u=new URL(location.href);u.search='';u.searchParams.set('view',view);Object.entries(extra).forEach(([k,v])=>u.searchParams.set(k,v));u.hash='';history[replace?'replaceState':'pushState']({},'',u);render()};
window.addEventListener('popstate',render);

function loadSession(){try{return JSON.parse(localStorage.getItem(STORE)||'null')}catch{return null}}
function saveSession(s){session=s;s?localStorage.setItem(STORE,JSON.stringify(s)):localStorage.removeItem(STORE)}
async function refreshIfNeeded(){if(!session?.refresh_token)return;if(session.expires_at&&Date.now()/1000<session.expires_at-90)return;try{const r=await fetch(SB_URL+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})});if(!r.ok)throw 0;const d=await r.json();saveSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in})}catch{saveSession(null)}}
async function request(path,{method='GET',body,auth=true,headers={},raw=false}={}){await refreshIfNeeded();const h={apikey:SB_KEY,...headers};if(!raw)h['Content-Type']='application/json';if(auth&&session?.access_token)h.Authorization='Bearer '+session.access_token;const r=await fetch(SB_URL+path,{method,headers:h,body:body===undefined?undefined:(raw?body:JSON.stringify(body))});if(raw){if(!r.ok)throw new Error(`Erro ${r.status}`);return r}let data=null;const text=await r.text();if(text){try{data=JSON.parse(text)}catch{data=text}}if(!r.ok){const e=new Error(data?.msg||data?.message||data?.error_description||data?.error||`Erro ${r.status}`);e.status=r.status;e.code=data?.code;throw e}return data}
async function authUser(){if(!session?.access_token)return null;try{return await request('/auth/v1/user')}catch{saveSession(null);return null}}
async function signIn(email,password){const d=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email,password},auth:false});saveSession({...d,expires_at:Math.floor(Date.now()/1000)+d.expires_in});return d.user}
async function signUp(email,password){const redirect_to=location.origin+'/?view=onboarding';const d=await request('/auth/v1/signup?redirect_to='+encodeURIComponent(redirect_to),{method:'POST',body:{email,password},auth:false});if(d.access_token)saveSession({...d,expires_at:Math.floor(Date.now()/1000)+(d.expires_in||3600)});return d}
async function signOut(){try{if(session)await request('/auth/v1/logout',{method:'POST'})}catch{}saveSession(null)}
function captureHash(){if(!location.hash.includes('access_token='))return false;const p=new URLSearchParams(location.hash.slice(1));const access_token=p.get('access_token'),refresh_token=p.get('refresh_token'),expires_in=Number(p.get('expires_in')||3600),type=p.get('type');if(access_token){saveSession({access_token,refresh_token,expires_in,expires_at:Math.floor(Date.now()/1000)+expires_in,token_type:'bearer'});history.replaceState({},'',location.pathname+'?view='+(type==='recovery'?'reset':'onboarding'));return true}return false}
async function profile(){const u=await authUser();if(!u)return null;const rows=await request(`/rest/v1/gti_missions_profiles?user_id=eq.${encodeURIComponent(u.id)}&select=*`);return rows?.[0]||null}
async function rpc(name,args={}){return request('/rest/v1/rpc/'+name,{method:'POST',body:args})}
async function stats(){try{return {...EMPTY,...await rpc('gti_missions_my_stats')}}catch{return {...EMPTY}}}
async function isAdmin(){try{return !!(await rpc('gti_missions_is_admin'))}catch{return false}}
async function customStatuses(){try{return await rpc('gti_missions_custom_challenge_statuses')||[]}catch{return []}}
function bmiValue(heightCm,weightKg){const h=Number(heightCm)/100,w=Number(weightKg);if(!h||!w||h<=0)return null;return w/(h*h)}
function bmiText(v){if(!v)return'Preencha altura e peso';if(v<18.5)return'Abaixo da faixa de referência';if(v<25)return'Faixa de referência geral';if(v<30)return'Acima da faixa de referência';return'Bem acima da faixa de referência'}
function suggestedWater(weightKg){const w=Number(weightKg);if(!w)return null;return Math.round(clamp(w*35,1500,4000)/25)*25}
function avatarFallback(name,size='normal'){return `<div class="avatar ${size==='small'?'avatar-small':''}">${esc((name||'G')[0].toUpperCase())}</div>`}
function storageUrl(url){if(!url)return null;if(url.startsWith('/object/'))return `${SB_URL}/storage/v1${url}`;try{return new URL(url,SB_URL).href}catch{return null}}
async function authenticatedImage(bucket,path){const p=path.split('/').map(encodeURIComponent).join('/');const response=await request(`/storage/v1/object/authenticated/${bucket}/${p}`,{raw:true});const blob=await response.blob();if(!blob.type.startsWith('image/'))throw new Error('Arquivo de imagem inválido.');return URL.createObjectURL(blob)}
async function signedAvatar(path){if(!path)return null;try{return await authenticatedImage(AVATAR_BUCKET,path)}catch{}try{const p=path.split('/').map(encodeURIComponent).join('/');const d=await request(`/storage/v1/object/sign/${AVATAR_BUCKET}/${p}`,{method:'POST',body:{expiresIn:3600}});return storageUrl(d?.signedURL||d?.signedUrl)}catch{return null}}
async function avatarHtml(path,name,size='normal'){const url=await signedAvatar(path);if(!url)return avatarFallback(name,size);return `<img class="avatar ${size==='small'?'avatar-small':''}" src="${esc(url)}" alt="Foto de ${esc(name)}">`}
async function uploadAvatar(file,userId){
  if(!file)return null;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Use JPG, PNG ou WEBP.');
  if(file.size>5*1024*1024)throw new Error('A foto deve ter no máximo 5 MB.');
  await refreshIfNeeded();
  const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg';
  const path=`${userId}/avatar-${Date.now()}.${ext}`;
  const r=await fetch(`${SB_URL}/storage/v1/object/${AVATAR_BUCKET}/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':file.type},body:file});
  if(!r.ok){let d={};try{d=await r.json()}catch{}throw new Error(d.message||d.error||'Não foi possível enviar a foto.');}
  return path;
}
async function deleteAvatar(path){if(!path)return;try{await refreshIfNeeded();const pp=path.split('/').map(encodeURIComponent).join('/');await fetch(`${SB_URL}/storage/v1/object/${AVATAR_BUCKET}/${pp}`,{method:'DELETE',headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token}})}catch{}}
async function signedCheckin(path,expiresIn=300){if(!path)return null;try{const pp=path.split('/').map(encodeURIComponent).join('/');const d=await request(`/storage/v1/object/sign/${CHECKIN_BUCKET}/${pp}`,{method:'POST',body:{expiresIn}});return storageUrl(d?.signedURL||d?.signedUrl)}catch{return null}}
async function uploadCheckinPhoto(blob,userId,challengeId){if(!blob)throw new Error('Tire a foto do check primeiro.');await refreshIfNeeded();const id=(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`);const path=`${userId}/${challengeId}/${id}.jpg`;const r=await fetch(`${SB_URL}/storage/v1/object/${CHECKIN_BUCKET}/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token,'Content-Type':'image/jpeg'},body:blob});if(!r.ok){let d={};try{d=await r.json()}catch{}throw new Error(d.message||d.error||'Não foi possível enviar a foto do check.')}return path}
async function discardCheckinPhoto(path){if(!path)return;try{await refreshIfNeeded();const pp=path.split('/').map(encodeURIComponent).join('/');await fetch(`${SB_URL}/storage/v1/object/${CHECKIN_BUCKET}/${pp}`,{method:'DELETE',headers:{apikey:SB_KEY,Authorization:'Bearer '+session.access_token}})}catch{}}
async function cameraCapture(mount){
  if(!window.isSecureContext)throw new Error('A câmera exige conexão HTTPS.');
  if(!navigator.mediaDevices?.getUserMedia)throw new Error('A câmera não está disponível neste navegador.');
  const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:1280}},audio:false});
  return new Promise((resolve,reject)=>{
    const stop=()=>stream.getTracks().forEach(t=>t.stop());
    mount.innerHTML=`<div class="camera-stage"><video id="checkVideo" autoplay muted playsinline></video><div class="camera-actions"><button class="primary" id="snapNow" type="button">📸 Tirar foto</button><button class="secondary" id="cancelCamera" type="button">Cancelar</button></div></div>`;
    const video=mount.querySelector('#checkVideo');video.srcObject=stream;
    mount.querySelector('#cancelCamera').onclick=()=>{stop();mount.innerHTML='';reject(new Error('Captura cancelada.'))};
    mount.querySelector('#snapNow').onclick=()=>{
      const vw=video.videoWidth||1280,vh=video.videoHeight||1280,scale=Math.min(1,1280/vw),canvas=document.createElement('canvas');
      canvas.width=Math.max(1,Math.round(vw*scale));canvas.height=Math.max(1,Math.round(vh*scale));
      canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);stop();
      canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Não foi possível capturar a foto.')),'image/jpeg',0.82);
    };
  });
}

function bindProofCamera({buttonId='openCamera',mountId='cameraMount',messageId='cameraMsg'}={}){
  const state={blob:null,previewUrl:null},button=document.getElementById(buttonId);
  if(!button)return state;
  const open=async()=>{
    const mount=document.getElementById(mountId),msg=document.getElementById(messageId);
    msg.innerHTML='';
    state.blob=null;
    if(state.previewUrl){URL.revokeObjectURL(state.previewUrl);state.previewUrl=null}
    try{
      state.blob=await cameraCapture(mount);
      state.previewUrl=URL.createObjectURL(state.blob);
      mount.innerHTML=`<div class="proof-ready"><img class="proof-preview" src="${state.previewUrl}" alt="Foto do check tirada agora"><div><b>Foto pronta ✓</b><p>Ela será enviada junto com este registro e apagada após 24 horas.</p><button class="secondary" id="retake" type="button">Tirar outra</button></div></div>`;
      document.getElementById('retake').onclick=open;
    }catch(err){
      if((err?.message||'')!=='Captura cancelada.')msg.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`;
    }
  };
  button.onclick=open;
  return state;
}

function shell(content,active='app'){return `<main class="app-shell">${content}</main><nav class="bottom-nav">${[['app','⌂','Início'],['aqua','💧','AquaXP'],['tech','⚡','Tech Rat'],['league','🏆','League'],['profile','◉','Perfil']].map(([v,i,l])=>`<a href="/?view=${v}" data-nav="${v}" class="${active===v?'active':''}"><span>${i}</span><small>${l}</small></a>`).join('')}</nav>`}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(a=>a.onclick=e=>{e.preventDefault();nav(a.dataset.nav)})}
async function requirePlayer(){const u=await authUser();if(!u||u.is_anonymous){nav('login',true);return null}const p=await profile();if(!p?.accepted_terms_at||p.terms_version!==TERMS){nav('onboarding',true);return null}return {u,p}}
function friendly(e){const m=(e?.message||'').toLowerCase();if(m.includes('invalid login'))return'E-mail ou senha inválidos.';if(m.includes('email not confirmed'))return'Confirme seu e-mail antes de entrar.';if(m.includes('rate limit'))return'Muitas tentativas. Tente novamente mais tarde.';if(m.includes('duplicate')||e?.code==='23505')return'Esse @username já está em uso.';if(m.includes('terms'))return'Atualize e aceite os Termos para continuar.';if(m.includes('admin required'))return'Essa ação é exclusiva da administração.';if(m.includes('camera proof required'))return'Tire uma foto agora para validar o check.';if(m.includes('invalid or expired camera proof'))return'A foto do check não foi validada. Tire outra foto agora.';if(m.includes('permission denied')&&m.includes('camera'))return'Permita o acesso à câmera para fazer o check.';return e?.message||'Não foi possível concluir agora.'}

async function render(){if(captureHash())return render();const url=new URL(location.href),view=url.searchParams.get('view')||'home';app.innerHTML='<main class="center"><div class="loader"></div><p>Carregando missão...</p></main>';try{if(view==='home')return renderHome();if(view==='login')return renderLogin();if(view==='forgot')return renderForgot();if(view==='reset')return renderReset();if(view==='terms')return renderTerms();if(view==='privacy')return renderPrivacy();if(view==='onboarding')return renderOnboarding();const player=await requirePlayer();if(!player)return;if(view==='aqua')return renderAqua();if(view==='tech')return renderTech();if(view==='league')return renderLeague();if(view==='profile')return renderProfile();if(view==='admin')return renderAdmin();if(view==='challenge')return renderCustomChallenge(url.searchParams.get('id'));return renderDashboard(player)}catch(e){app.innerHTML=`<main class="auth-page"><section class="auth-card"><div class="brand-pill">ERRO</div><h1>Deu ruim nessa missão.</h1><p>${esc(friendly(e))}</p><button class="primary" id="retry">Tentar novamente</button></section></main>`;document.getElementById('retry').onclick=render}}

async function renderHome(){const u=await authUser();app.innerHTML=`<main class="landing"><section class="hero"><div class="brand-pill">GTI • GALERA DO TI</div><h1>GTI <span>MISSIONS</span></h1><p class="tagline">Missões reais. XP de verdade.</p><p class="lead">Transforme hábitos fora da tela em sequência, selos, níveis e competição saudável.</p><div class="hero-actions"><button class="primary" id="start">${u?'Ir para minha Home →':'Começar agora →'}</button><button class="install" id="install" hidden>📲 Instalar app</button></div><p class="hero-note">A primeira tela do player é sempre a Home. Você escolhe qual missão quer abrir.</p></section><section class="mission-preview"><article class="mission-card aqua"><div class="mission-icon">💧</div><div><b>AquaXP League</b><p>7 dias na semana: conclua a meta diária para fechar o selo 7/7.</p></div><span>ATIVA</span></article><article class="mission-card rat"><div class="mission-icon">⚡</div><div><b>Tech Rat</b><p>Configure de 3 a 7 dias de treino por semana.</p></div><span>ATIVA</span></article><article class="mission-card custom"><div class="mission-icon">🎯</div><div><b>Missões da comunidade</b><p>Em breve, novos desafios.</p></div><span>EM BREVE</span></article></section><section class="feature-strip"><div><strong>🔥</strong><b>Ofensiva</b><span>consistência diária</span></div><div><strong>🏅</strong><b>Selos</b><span>conquistas semanais</span></div><div><strong>🏆</strong><b>League</b><span>ranking mensal</span></div><div><strong>⚡</strong><b>Níveis</b><span>progresso permanente</span></div></section><footer class="site-footer"><span>GTI Missions • Galera do TI</span><nav><a href="/?view=terms" data-nav="terms">Termos</a><a href="/?view=privacy" data-nav="privacy">Privacidade</a></nav></footer></main>`;document.getElementById('start').onclick=async()=>{if(!u)return nav('login');const p=await profile();nav(p?.accepted_terms_at&&p.terms_version===TERMS?'app':'onboarding')};bindNav();installSupport()}
function installSupport(){let ev;const b=document.getElementById('install');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();ev=e;if(b)b.hidden=false},{once:true});if(b)b.onclick=async()=>{if(ev){await ev.prompt();ev=null;b.hidden=true}}}

function renderLogin(){app.innerHTML=`<main class="auth-page"><section class="auth-card"><button class="back-link" data-nav="home">← Voltar</button><div class="brand-pill">GTI MISSIONS</div><h1 id="authTitle">Volte para a missão.</h1><p>Entre e você será levado para a Home do GTI Missions, não para um desafio específico.</p><form id="authForm"><label>E-mail<input id="email" type="email" autocomplete="email" required></label><label>Senha<input id="password" type="password" autocomplete="current-password" required maxlength="72"></label><button class="primary" id="submit">Entrar</button></form><div id="msg"></div><button class="link-btn" id="mode">Ainda não tenho conta</button><button class="forgot-link" data-nav="forgot">Esqueci minha senha</button></section></main>`;bindNav();let mode='login';const form=document.getElementById('authForm'),msg=document.getElementById('msg'),btn=document.getElementById('submit');document.getElementById('mode').onclick=()=>{mode=mode==='login'?'signup':'login';document.getElementById('authTitle').textContent=mode==='login'?'Volte para a missão.':'Crie seu player.';document.getElementById('mode').textContent=mode==='login'?'Ainda não tenho conta':'Já tenho conta';btn.textContent=mode==='login'?'Entrar':'Criar conta';document.getElementById('password').minLength=mode==='signup'?10:0;msg.innerHTML=''};form.onsubmit=async e=>{e.preventDefault();btn.disabled=true;msg.innerHTML='';try{const email=document.getElementById('email').value.trim().toLowerCase(),pass=document.getElementById('password').value;if(mode==='signup'){const d=await signUp(email,pass);if(d.access_token)nav('onboarding');else msg.innerHTML='<div class="success">Conta criada. Confira seu e-mail para confirmar o acesso.</div>'}else{await signIn(email,pass);const p=await profile();nav(p?.accepted_terms_at&&p.terms_version===TERMS?'app':'onboarding')}}catch(err){msg.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}finally{btn.disabled=false}}}
function renderForgot(){app.innerHTML=`<main class="auth-page"><section class="auth-card"><button class="back-link" data-nav="login">← Voltar ao login</button><div class="brand-pill">RECUPERAR ACESSO</div><h1>Redefinir senha.</h1><p>Informe seu e-mail.</p><form id="f"><label>E-mail<input id="email" type="email" required></label><button class="primary">Enviar recuperação</button></form><div id="msg"></div></section></main>`;bindNav();document.getElementById('f').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('msg');try{await request('/auth/v1/recover?redirect_to='+encodeURIComponent(location.origin+'/?view=reset'),{method:'POST',body:{email:document.getElementById('email').value.trim().toLowerCase()},auth:false})}catch{}m.innerHTML='<div class="success">Se esse e-mail estiver cadastrado, você receberá as instruções.</div>'}}
function renderReset(){app.innerHTML=`<main class="auth-page"><section class="auth-card"><div class="brand-pill">NOVA SENHA</div><h1>Crie uma nova senha.</h1>${session?'<form id="f"><label>Nova senha<input id="p1" type="password" minlength="10" maxlength="72" required></label><label>Confirmar<input id="p2" type="password" minlength="10" maxlength="72" required></label><button class="primary">Atualizar senha</button></form>':'<div class="notice">Link inválido ou expirado.</div>'}<div id="msg"></div></section></main>`;if(!session)return;document.getElementById('f').onsubmit=async e=>{e.preventDefault();const p1=document.getElementById('p1').value,p2=document.getElementById('p2').value,m=document.getElementById('msg');if(p1!==p2){m.innerHTML='<div class="notice">As senhas não coincidem.</div>';return}try{await request('/auth/v1/user',{method:'PUT',body:{password:p1}});await signOut();nav('login')}catch(err){m.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}}

async function renderOnboarding(){const u=await authUser();if(!u||u.is_anonymous)return nav('login',true);const p=await profile()||{},suggested=suggestedWater(p.weight_kg)||p.water_target_ml||2000;app.innerHTML=`<main class="auth-page"><section class="auth-card wide"><div class="brand-pill">PERFIL • TERMOS 1.2</div><h1>Monte seu player.</h1><p>Depois de salvar, você entra na <b>Home</b> e escolhe a missão. Foto, altura e peso são opcionais.</p><form id="f"><div class="profile-photo-picker"><div id="avatarPreview">${await avatarHtml(p.avatar_path,p.display_name||'G')}</div><label class="secondary file-label">🖼️ Anexar foto<input id="avatarFile" type="file" accept="image/jpeg,image/png,image/webp" hidden></label><label class="secondary file-label">📷 Abrir câmera<input id="avatarCameraFile" type="file" accept="image/jpeg,image/png,image/webp" capture="user" hidden></label></div><div class="field-pair"><label>Nome/apelido<input id="name" required maxlength="60" value="${esc(p.display_name||'')}"></label><label>@username<input id="username" required pattern="[A-Za-z0-9._-]{3,30}" maxlength="30" value="${esc(p.username||'')}"></label></div><div class="field-pair"><label>Altura (cm)<input id="height" type="number" min="100" max="250" step="0.1" value="${p.height_cm||''}" placeholder="Ex.: 168"></label><label>Peso (kg)<input id="weight" type="number" min="30" max="300" step="0.1" value="${p.weight_kg||''}" placeholder="Ex.: 72.5"></label></div><div class="health-card"><div><small>IMC estimado</small><strong id="bmi">—</strong><span id="bmiLabel">Preencha altura e peso</span></div><div><small>Referência de água</small><strong id="waterRef">${fmt(suggested)} ml</strong><span>estimativa simples; não é prescrição</span></div></div><label>Meta diária de água (ml)<div class="inline-input"><input id="water" type="number" min="1000" max="4000" step="1" value="${p.water_target_ml||suggested}"><button class="secondary" type="button" id="useRef">Usar referência</button></div><small class="field-help">Você pode usar valor quebrado/exato, por exemplo 2375 ml.</small></label><div class="field-pair"><label>Seu recipiente<select id="container"><option>Garrafa</option><option>Copo</option><option>Squeeze</option><option>Caneca</option><option>Outro</option></select></label><label>Volume exato (ml)<input id="containerMl" type="number" min="50" max="2000" step="1" value="${p.water_container_ml||475}"></label></div><div class="preset-row"><span>Atalhos:</span>${[200,250,300,350,475,500,600,750,1000].map(x=>`<button type="button" data-cup="${x}">${x} ml</button>`).join('')}</div><label>Academia / atividade física por semana<select id="exercise">${[3,4,5,6,7].map(x=>`<option value="${x}">${x} dias</option>`).join('')}</select></label><div class="privacy-callout">💧 AquaXP: o selo semanal exige <b>7/7 dias</b>. ⚡ Tech Rat: você escolhe de <b>3 a 7 dias</b>.</div><label class="check-row"><input id="accept" type="checkbox" required ${p.accepted_terms_at&&p.terms_version===TERMS?'checked':''}><span>Li e aceito os <a href="/?view=terms" target="_blank">Termos 1.2</a> e a <a href="/?view=privacy" target="_blank">Política de Privacidade 1.2</a>.</span></label><button class="primary">Salvar e ir para a Home →</button></form><div id="msg"></div></section></main>`;document.getElementById('container').value=p.water_container_label||'Copo';document.getElementById('exercise').value=Math.max(3,p.exercise_weekly_target||3);const height=document.getElementById('height'),weight=document.getElementById('weight'),water=document.getElementById('water');let avatarFile=null;function updateHealth(){const b=bmiValue(height.value,weight.value),wr=suggestedWater(weight.value);document.getElementById('bmi').textContent=b?b.toFixed(1):'—';document.getElementById('bmiLabel').textContent=bmiText(b);document.getElementById('waterRef').textContent=wr?`${fmt(wr)} ml`:'—'}height.oninput=updateHealth;weight.oninput=updateHealth;updateHealth();document.getElementById('useRef').onclick=()=>{const wr=suggestedWater(weight.value);if(wr)water.value=wr};document.querySelectorAll('[data-cup]').forEach(b=>b.onclick=()=>document.getElementById('containerMl').value=b.dataset.cup);const previewAvatar=e=>{avatarFile=e.target.files?.[0]||null;if(avatarFile){const url=URL.createObjectURL(avatarFile);document.getElementById('avatarPreview').innerHTML=`<img class="avatar" src="${url}" alt="Prévia">`}};document.getElementById('avatarFile').onchange=previewAvatar;document.getElementById('avatarCameraFile').onchange=previewAvatar;document.getElementById('f').onsubmit=async e=>{e.preventDefault();const msg=document.getElementById('msg');msg.innerHTML='';const payload={user_id:u.id,display_name:document.getElementById('name').value.trim(),username:document.getElementById('username').value.trim().replace(/^@/,''),water_target_ml:+water.value,exercise_weekly_target:+document.getElementById('exercise').value,water_container_label:document.getElementById('container').value,water_container_ml:+document.getElementById('containerMl').value,height_cm:height.value?+height.value:null,weight_kg:weight.value?+weight.value:null,accepted_terms_at:new Date().toISOString(),terms_version:TERMS};try{await request('/rest/v1/gti_missions_profiles?on_conflict=user_id',{method:'POST',body:payload,headers:{Prefer:'resolution=merge-duplicates,return=minimal'}});if(avatarFile){const path=await uploadAvatar(avatarFile,u.id);const updated=await request(`/rest/v1/gti_missions_profiles?user_id=eq.${encodeURIComponent(u.id)}&select=avatar_path`,{method:'PATCH',body:{avatar_path:path},headers:{Prefer:'return=representation'}});if(updated?.[0]?.avatar_path!==path)throw new Error('A foto foi enviada, mas o perfil não foi atualizado.')}nav('app')}catch(err){msg.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}}

async function renderDashboard(player){const [s,rows,custom,admin]=await Promise.all([stats(),rpc('gti_missions_leaderboard'),customStatuses(),isAdmin()]),rank=(rows||[]).find(r=>r.user_id===player.u.id)?.rank||'—',pct=Math.min(100,Math.round((s.water_today_ml/s.water_target_ml)*100)),avatar=await avatarHtml(player.p.avatar_path,player.p.display_name,'small');const customCards=custom.map(c=>`<button class="mission-card custom challenge-card" data-challenge="${c.id}"><div class="mission-icon">${esc(c.icon)}</div><div><b>${esc(c.title)}</b><p>${c.joined?`${c.week_completed_days}/${c.weekly_target_days} dias concluídos nesta semana`:'Novo desafio disponível • toque para ver'}</p></div><span>${c.today_completed?'✓ HOJE':c.joined?'ABRIR →':'NOVO'}</span></button>`).join('');app.innerHTML=shell(`<header class="top"><div class="user-head">${avatar}<div><small>GTI MISSIONS</small><h1>Oi, ${esc(player.p.display_name)}.</h1></div></div>${admin?'<button class="admin-chip" id="adminBtn">⚙ ADM</button>':`<div class="level-chip">LVL ${level(s.total_xp)}</div>`}</header><section class="streak-card"><div><small>OFENSIVA</small><strong>🔥 ${s.activity_streak} dias</strong><p>Conta a cada dia em que você conquista XP.</p></div><div class="xp-circle">${s.total_xp}<small>XP</small></div></section><section class="level-bar"><div><b>${levelName(s.total_xp)}</b><span>${s.total_xp%500}/500 XP</span></div><progress value="${s.total_xp%500}" max="500"></progress></section><h2 class="section-title">Suas missões</h2><section class="cards-grid"><a href="/?view=aqua" data-nav="aqua" class="mission-card aqua"><div class="mission-icon">💧</div><div><b>AquaXP League</b><p>${fmt(s.water_today_ml)} / ${fmt(s.water_target_ml)} ml • ${s.water_week_days}/7 dias no selo</p><div class="mini-progress"><i style="width:${pct}%"></i></div></div><span>${pct}%</span></a><a href="/?view=tech" data-nav="tech" class="mission-card rat"><div class="mission-icon">⚡</div><div><b>Tech Rat</b><p>${s.exercise_week_days}/${s.exercise_week_target} dias de treino nesta semana.</p></div><span>IR →</span></a>${customCards}</section>${custom.length===0?'<section class="empty-card"><b>🎯 Em breve, novos desafios.</b><p>Fique de olho nas próximas missões da comunidade.</p></section>':''}<section class="stats"><div><small>League</small><b>#${rank}</b></div><div><small>Selos</small><b>${s.badges}</b></div><div><small>XP no mês</small><b>${s.monthly_xp}</b></div><div><small>Nível</small><b>${levelName(s.total_xp)}</b></div></section>`);bindNav();document.querySelectorAll('[data-challenge]').forEach(b=>b.onclick=()=>nav('challenge',false,{id:b.dataset.challenge}));if(admin)document.getElementById('adminBtn').onclick=()=>nav('admin')}

async function renderAqua(){const [s,p,u]=await Promise.all([stats(),profile(),authUser()]),pct=Math.min(100,Math.round((s.water_today_ml/s.water_target_ml)*100));app.innerHTML=shell(`<header class="page-head"><div><small>MISSÃO 01</small><h1>💧 AquaXP League</h1><p>Meta diária + selo semanal 7/7. Sem pausa para fechar a semana.</p></div><div class="streak-mini">🏅 ${s.water_week_days}/7</div></header><section class="water-orb"><div class="orb" style="--pct:${pct}%"><strong>${pct}%</strong><span>${fmt(s.water_today_ml)} / ${fmt(s.water_target_ml)} ml</span></div></section><section class="camera-proof"><div class="section-row"><div><b>📸 Foto da água</b><p>Tire uma foto agora antes de registrar. Não abre a galeria e a imagem fica disponível por somente 24 horas.</p></div><span class="proof-required">OBRIGATÓRIA</span></div><button class="secondary full" id="openCamera" type="button">Abrir câmera</button><div id="cameraMount"></div><div id="cameraMsg"></div></section><section class="quick-log"><div class="section-row"><h2>Registrar água</h2><small>Hoje</small></div><div class="button-grid">${[200,250,300,350,475,500,750].map(x=>`<button data-water="${x}">+${x} ml</button>`).join('')}<button data-water="${p.water_container_ml}">+ ${esc(p.water_container_label)} <small>${p.water_container_ml} ml</small></button></div><form class="custom-water" id="customWater"><label>Outro valor exato (ml)<input id="customMl" type="number" min="50" max="2000" step="1" placeholder="Ex.: 425"></label><button class="secondary">Registrar</button></form><div id="msg"></div></section><section class="week-progress"><div class="section-row"><h2>Selo da semana</h2><span>🏅</span></div><div class="week-dots">${Array.from({length:7},(_,i)=>`<i class="${i<s.water_week_days?'done':''}"></i>`).join('')}</div><p>${s.water_week_days>=7?'Selo AquaXP 7/7 garantido nesta semana.':`${s.water_week_days}/7 dias com a meta concluída.`}</p></section><section class="rule-card"><b>Como ganha XP?</b><p>Até 5 registros por dia rendem +5 XP. Concluir a meta rende +50 XP. Fechar os 7 dias da semana libera selo +100 XP.</p><small>Beber além da meta não gera XP extra.</small></section>`,'aqua');bindNav();const proof=bindProofCamera();async function log(amount){const m=document.getElementById('msg');let path=null;if(!proof.blob){m.innerHTML='<div class="notice">Abra a câmera e tire uma foto da água antes de registrar.</div>';return}document.querySelectorAll('[data-water]').forEach(x=>x.disabled=true);try{path=await uploadCheckinPhoto(proof.blob,u.id,'aqua');const d=await rpc('gti_missions_log_water',{p_amount_ml:+amount,p_photo_path:path});m.innerHTML=`<div class="success">${d?.xp_awarded?`+${d.xp_awarded} XP desbloqueado ⚡`:'Água registrada 💧'} • Foto validada por 24h.</div>`;setTimeout(()=>renderAqua(),350)}catch(err){if(path)await discardCheckinPhoto(path);m.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`;document.querySelectorAll('[data-water]').forEach(x=>x.disabled=false)}}document.querySelectorAll('[data-water]').forEach(b=>b.onclick=()=>log(b.dataset.water));document.getElementById('customWater').onsubmit=e=>{e.preventDefault();const v=+document.getElementById('customMl').value;if(v)log(v)}}

async function renderTech(){const [s,u]=await Promise.all([stats(),authUser()]);app.innerHTML=shell(`<header class="page-head"><div><small>MISSÃO 02</small><h1>⚡ Tech Rat</h1><p>Sua meta pode ser de 3 a 7 dias por semana.</p></div><div class="streak-mini">${s.exercise_week_days}/${s.exercise_week_target}</div></header><section class="week-progress"><h2>Meta da semana</h2><div class="week-dots">${Array.from({length:s.exercise_week_target},(_,i)=>`<i class="${i<s.exercise_week_days?'done':''}"></i>`).join('')}</div><p>${s.exercise_week_days>=s.exercise_week_target?'Selo Tech Rat garantido 🏅':`Faltam ${Math.max(0,s.exercise_week_target-s.exercise_week_days)} dia(s) de movimento.`}</p></section><section class="camera-proof"><div class="section-row"><div><b>📸 Foto do treino</b><p>Tire uma foto agora antes de concluir. Não abre a galeria e a imagem fica disponível por somente 24 horas.</p></div><span class="proof-required">OBRIGATÓRIA</span></div><button class="secondary full" id="openCamera" type="button">Abrir câmera</button><div id="cameraMount"></div><div id="cameraMsg"></div></section><form class="exercise-form" id="f"><h2>Registrar exercício</h2><div class="chips">${['Academia','Corrida','Caminhada','Bike','Dança','Yoga','Funcional','Natação'].map((x,i)=>`<button type="button" data-ex="${x}" class="${i===0?'selected':''}">${x}</button>`).join('')}</div><label>Exercício<input id="ex" value="Academia" maxlength="80" required></label><label>Duração em minutos<input id="duration" type="number" min="1" max="300" value="30" required></label><button class="primary" type="submit">Concluir treino</button><div id="msg"></div></form><section class="rule-card"><b>Regra anti-farm</b><p>Primeiro treino válido do dia: 5–19 min = +15 XP; 20+ min = +30 XP. Meta semanal = selo +100 XP.</p><small>O app não exige treino todos os dias; a frequência é configurada entre 3 e 7.</small></section>`,'tech');bindNav();const proof=bindProofCamera();document.querySelectorAll('[data-ex]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-ex]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');document.getElementById('ex').value=b.dataset.ex});document.getElementById('f').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('msg'),btn=e.submitter||e.target.querySelector('button[type=submit]');let path=null;if(!proof.blob){m.innerHTML='<div class="notice">Abra a câmera e tire uma foto do treino antes de concluir.</div>';return}try{btn.disabled=true;path=await uploadCheckinPhoto(proof.blob,u.id,'tech');const d=await rpc('gti_missions_log_exercise',{p_exercise_name:document.getElementById('ex').value.trim(),p_duration_minutes:+document.getElementById('duration').value,p_photo_path:path});m.innerHTML=`<div class="success">${d?.xp_awarded?`Treino salvo. +${d.xp_awarded} XP ⚡`:'Treino salvo. O XP do dia já estava contabilizado.'} Foto validada por 24h.</div>`;setTimeout(()=>renderTech(),450)}catch(err){if(path)await discardCheckinPhoto(path);btn.disabled=false;m.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}}

async function renderCustomChallenge(id){
  const all=await customStatuses(),c=all.find(x=>x.id===id);if(!c)return nav('app',true);
  const u=await authUser();
  const pct=c.mode==='quantity'?Math.min(100,Math.round((Number(c.today_value)/Number(c.daily_target))*100)):(c.today_completed?100:0);
  const proofBlock=c.requires_photo&&!c.today_completed?`<section class="camera-proof"><div class="section-row"><div><b>📸 Foto de check</b><p>Tirada agora pela câmera do app. Não abre a galeria e a foto é apagada automaticamente após 24h.</p></div><span class="proof-required">OBRIGATÓRIA</span></div><button class="secondary full" id="openCamera" type="button">Abrir câmera</button><div id="cameraMount"></div><div id="cameraMsg"></div></section>`:'';
  app.innerHTML=shell(`<header class="page-head"><div><small>MISSÃO DA COMUNIDADE</small><h1>${esc(c.icon)} ${esc(c.title)}</h1><p>${esc(c.description||'Desafio criado pela administração do GTI Missions.')}</p></div><div class="streak-mini">${c.week_completed_days}/${c.weekly_target_days}</div></header>${!c.joined?`<section class="join-card"><h2>Pronto para essa missão?</h2><p>Meta semanal: ${c.weekly_target_days} dia(s) • +${c.xp_per_day} XP por dia concluído • +${c.weekly_bonus_xp} XP ao fechar a semana.${c.requires_photo?' • 📸 Foto tirada na hora para validar o check.':''}</p><button class="primary" id="join">Iniciar desafio →</button></section>`:`<section class="week-progress"><div class="section-row"><h2>Progresso da semana</h2><b>${c.week_completed_days}/${c.weekly_target_days}</b></div><div class="week-dots">${Array.from({length:c.weekly_target_days},(_,i)=>`<i class="${i<c.week_completed_days?'done':''}"></i>`).join('')}</div></section>${proofBlock}${c.mode==='checkin'?`<section class="quick-log"><h2>${c.today_completed?'Missão de hoje concluída ✓':'Check-in de hoje'}</h2><p>${c.today_completed?'Seu XP de hoje já foi contabilizado.':'Confirme quando concluir a missão de hoje.'}</p><button class="primary" id="customLog" ${c.today_completed?'disabled':''}>${c.today_completed?'Concluído hoje':'Concluir hoje +'+c.xp_per_day+' XP'}</button><div id="msg"></div></section>`:`<section class="quick-log"><h2>Meta de hoje</h2><div class="mini-progress big"><i style="width:${pct}%"></i></div><p>${fmt(c.today_value)} / ${fmt(c.daily_target)} ${esc(c.unit_label)}</p><form id="quantityForm"><label>Adicionar ${esc(c.unit_label)}<input id="qValue" type="number" min="0.01" step="0.01" required></label><label>Observação opcional<input id="qNote" maxlength="180" placeholder="Opcional"></label><button class="primary">Registrar</button></form><div id="msg"></div></section>`}<section class="rule-card"><b>Regras desta missão</b><p>${c.weekly_target_days} dia(s) por semana • +${c.xp_per_day} XP ao concluir o dia • +${c.weekly_bonus_xp} XP ao fechar a meta semanal.${c.requires_photo?' • Foto de prova privada, disponível por no máximo 24h.':''}</p></section>`}`,'app');
  bindNav();
  if(!c.joined){document.getElementById('join').onclick=async()=>{try{await rpc('gti_missions_join_challenge',{p_challenge_id:c.id});renderCustomChallenge(c.id)}catch(e){alert(friendly(e))}};return}
  let proofBlob=null,previewUrl=null;
  const cameraButton=document.getElementById('openCamera');
  const bindCamera=()=>{if(!cameraButton)return;cameraButton.onclick=async()=>{const mount=document.getElementById('cameraMount'),cm=document.getElementById('cameraMsg');cm.innerHTML='';try{proofBlob=await cameraCapture(mount);if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(proofBlob);mount.innerHTML=`<div class="proof-ready"><img class="proof-preview" src="${previewUrl}" alt="Foto do check tirada agora"><div><b>Foto pronta ✓</b><p>Ela só será enviada quando você concluir o check.</p><button class="secondary" id="retake" type="button">Tirar outra</button></div></div>`;document.getElementById('retake').onclick=cameraButton.onclick}catch(err){if((err?.message||'')!=='Captura cancelada.')cm.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}};
  bindCamera();
  async function uploadProofIfNeeded(willComplete){
    if(!c.requires_photo||c.today_completed||!willComplete)return null;
    if(!proofBlob)throw new Error('Camera proof required');
    return uploadCheckinPhoto(proofBlob,u.id,c.id);
  }
  if(c.mode==='checkin'){
    const b=document.getElementById('customLog');if(b)b.onclick=async()=>{const m=document.getElementById('msg');let path=null;try{b.disabled=true;path=await uploadProofIfNeeded(true);const d=await rpc('gti_missions_log_custom_challenge',{p_challenge_id:c.id,p_value:1,p_note:null,p_photo_path:path});m.innerHTML=`<div class="success">Missão concluída. +${d.xp_awarded||c.xp_per_day} XP ⚡${path?' Foto validada por 24h.':''}</div>`;setTimeout(()=>renderCustomChallenge(c.id),500)}catch(e){if(path)await discardCheckinPhoto(path);b.disabled=false;m.innerHTML=`<div class="notice">${esc(friendly(e))}</div>`}}
  }else{
    document.getElementById('quantityForm').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('msg'),btn=e.submitter||e.target.querySelector('button[type=submit]');let path=null;try{btn.disabled=true;const value=+document.getElementById('qValue').value,willComplete=Number(c.today_value)+value>=Number(c.daily_target);path=await uploadProofIfNeeded(willComplete);const d=await rpc('gti_missions_log_custom_challenge',{p_challenge_id:c.id,p_value:value,p_note:document.getElementById('qNote').value.trim()||null,p_photo_path:path});m.innerHTML=`<div class="success">Registro salvo${d.xp_awarded?`. +${d.xp_awarded} XP ⚡`:'.'}${path?' Foto validada por 24h.':''}</div>`;setTimeout(()=>renderCustomChallenge(c.id),500)}catch(err){if(path)await discardCheckinPhoto(path);btn.disabled=false;m.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}
  }
}

async function renderLeague(){const rows=await rpc('gti_missions_leaderboard'),u=await authUser();const rendered=[];for(const r of rows||[]){const av=await avatarHtml(r.avatar_path,r.display_name,'small');rendered.push(`<article class="${r.user_id===u.id?'me':''}"><strong>#${r.rank}</strong><div class="league-user">${av}<div><b>${esc(r.display_name)}</b><small>@${esc(r.username)}</small></div></div><span>${r.xp} XP</span></article>`)}app.innerHTML=shell(`<header class="page-head"><div><small>SEASON MENSAL</small><h1>🏆 GTI League</h1><p>O ranking zera todo mês. XP total, nível e selos ficam.</p></div></header><div class="league-note">A League compara <b>XP de consistência</b>, não litros, peso ou minutos brutos.</div><section class="leaderboard">${rendered.length?rendered.join(''):'<div class="empty">A League começa assim que os primeiros players pontuarem.</div>'}</section>`,'league');bindNav()}

async function renderProfile(){
  const p=await profile(),s=await stats(),u=await authUser(),admin=await isAdmin(),badges=await request(`/rest/v1/gti_missions_weekly_badges?user_id=eq.${encodeURIComponent(u.id)}&select=*&order=week_start.desc`),customBadges=await request(`/rest/v1/gti_missions_challenge_badges?user_id=eq.${encodeURIComponent(u.id)}&select=*,gti_missions_challenges(title,icon)&order=week_start.desc`),av=await avatarHtml(p.avatar_path,p.display_name),bmi=bmiValue(p.height_cm,p.weight_kg),waterRef=suggestedWater(p.weight_kg);
  let adminRole=null;if(admin){try{const ar=await request(`/rest/v1/gti_missions_admins?user_id=eq.${encodeURIComponent(u.id)}&select=role`);adminRole=ar?.[0]?.role||'admin'}catch{adminRole='admin'}}
  app.innerHTML=shell(`<header class="profile-head">${av}<h1>${esc(p.display_name)}</h1><p>@${esc(p.username)}</p><div class="level-chip">LVL ${level(s.total_xp)} • ${levelName(s.total_xp)}</div>${admin?`<div class="owner-chip">🛡️ ${adminRole==='owner'?'Super Admin':'Admin'}</div>`:''}</header><section class="stats"><div><small>XP total</small><b>${s.total_xp}</b></div><div><small>Selos</small><b>${s.badges}</b></div><div><small>Ofensiva</small><b>🔥 ${s.activity_streak}</b></div><div><small>XP mês</small><b>${s.monthly_xp}</b></div></section>${p.height_cm&&p.weight_kg?`<section class="health-card profile-health"><div><small>IMC estimado</small><strong>${bmi.toFixed(1)}</strong><span>${bmiText(bmi)}</span></div><div><small>Referência de água</small><strong>${fmt(waterRef)} ml</strong><span>Sua meta: ${fmt(p.water_target_ml)} ml</span></div></section>`:''}<div class="profile-actions"><button class="secondary" id="photo">🖼️ Anexar foto</button><button class="secondary" id="photoCamera">📷 Abrir câmera</button><input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp" hidden><input id="photoCameraFile" type="file" accept="image/jpeg,image/png,image/webp" capture="user" hidden><button class="secondary" id="edit">⚙️ Editar perfil e metas</button>${admin?'<button class="primary" id="admin">🛡️ Administração</button>':''}</div><div id="editor"></div><h2 class="section-title">Coleção de selos</h2><section class="badges">${badges?.map(b=>`<article><span>${b.mission==='aqua'?'💧':'⚡'}</span><div><b>${esc(b.label)}</b><small>${new Date(b.week_start+'T12:00:00').toLocaleDateString('pt-BR')}</small></div></article>`).join('')||''}${customBadges?.map(b=>`<article><span>${esc(b.gti_missions_challenges?.icon||'🎯')}</span><div><b>${esc(b.label)}</b><small>${new Date(b.week_start+'T12:00:00').toLocaleDateString('pt-BR')}</small></div></article>`).join('')||''}${(!badges?.length&&!customBadges?.length)?'<div class="empty">Seu primeiro selo aparece aqui quando fechar uma missão semanal.</div>':''}</section><section class="account-actions"><button class="secondary" id="logout">Sair da conta</button><button class="danger" id="delete">Apagar meus dados do GTI Missions</button></section><div class="profile-legal"><a href="/?view=terms" data-nav="terms">Termos</a><a href="/?view=privacy" data-nav="privacy">Privacidade</a></div><div id="msg"></div>`,'profile');
  bindNav();
  document.getElementById('logout').onclick=async()=>{await signOut();nav('home')};
  if(admin)document.getElementById('admin').onclick=()=>nav('admin');
  document.getElementById('photo').onclick=()=>document.getElementById('photoFile').click();
  document.getElementById('photoCamera').onclick=()=>document.getElementById('photoCameraFile').click();
  const handleProfilePhoto=async e=>{const f=e.target.files?.[0];if(!f)return;const msg=document.getElementById('msg'),buttons=[document.getElementById('photo'),document.getElementById('photoCamera')];let newPath=null;try{buttons.forEach(button=>button.disabled=true);msg.innerHTML='<div class="notice">Enviando e atualizando sua foto...</div>';newPath=await uploadAvatar(f,u.id);const updated=await request(`/rest/v1/gti_missions_profiles?user_id=eq.${encodeURIComponent(u.id)}&select=avatar_path`,{method:'PATCH',body:{avatar_path:newPath},headers:{Prefer:'return=representation'}});if(updated?.[0]?.avatar_path!==newPath)throw new Error('A foto foi enviada, mas o perfil não foi atualizado.');if(p.avatar_path&&p.avatar_path!==newPath)await deleteAvatar(p.avatar_path);await renderProfile()}catch(err){if(newPath)await deleteAvatar(newPath);buttons.forEach(button=>button.disabled=false);e.target.value='';msg.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}};
  document.getElementById('photoFile').onchange=handleProfilePhoto;
  document.getElementById('photoCameraFile').onchange=handleProfilePhoto;
  document.getElementById('delete').onclick=async()=>{if(!confirm('Apagar perfil, registros, XP, selos e participação em desafios? Essa ação não pode ser desfeita.'))return;try{await deleteAvatar(p.avatar_path);await rpc('gti_missions_delete_my_data');await signOut();nav('home')}catch(err){document.getElementById('msg').innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}};
  document.getElementById('edit').onclick=()=>{const ed=document.getElementById('editor');ed.innerHTML=`<form class="settings-card" id="pf"><div class="field-pair"><label>Nome/apelido<input id="n" value="${esc(p.display_name)}" maxlength="60" required></label><label>@username<input id="un" value="${esc(p.username)}" pattern="[A-Za-z0-9._-]{3,30}" required></label></div><div class="field-pair"><label>Altura (cm)<input id="ht" type="number" min="100" max="250" step="0.1" value="${p.height_cm||''}"></label><label>Peso (kg)<input id="wk" type="number" min="30" max="300" step="0.1" value="${p.weight_kg||''}"></label></div><label>Meta de água (ml)<input id="wt" type="number" min="1000" max="4000" step="1" value="${p.water_target_ml}"></label><div class="field-pair"><label>Recipiente<select id="cl"><option>Garrafa</option><option>Copo</option><option>Squeeze</option><option>Caneca</option><option>Outro</option></select></label><label>Volume exato (ml)<input id="cm" type="number" min="50" max="2000" step="1" value="${p.water_container_ml}"></label></div><label>Academia / atividade por semana<select id="et">${[3,4,5,6,7].map(x=>`<option value="${x}">${x} dias</option>`).join('')}</select></label><p class="field-help">AquaXP continua 7/7. A meta de treino pode ficar entre 3 e 7 dias. Metas já iniciadas ficam congeladas no período.</p><button class="primary">Salvar alterações</button></form>`;document.getElementById('cl').value=p.water_container_label;document.getElementById('et').value=Math.max(3,p.exercise_weekly_target);document.getElementById('pf').onsubmit=async e=>{e.preventDefault();try{const body={display_name:document.getElementById('n').value.trim(),username:document.getElementById('un').value.trim().replace(/^@/,''),height_cm:document.getElementById('ht').value?+document.getElementById('ht').value:null,weight_kg:document.getElementById('wk').value?+document.getElementById('wk').value:null,water_target_ml:+document.getElementById('wt').value,water_container_label:document.getElementById('cl').value,water_container_ml:+document.getElementById('cm').value,exercise_weekly_target:+document.getElementById('et').value};await request(`/rest/v1/gti_missions_profiles?user_id=eq.${encodeURIComponent(u.id)}`,{method:'PATCH',body,headers:{Prefer:'return=minimal'}});renderProfile()}catch(err){document.getElementById('msg').innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}}}
}

async function renderAdmin(){
  if(!(await isAdmin()))return nav('app',true);
  const rows=await request('/rest/v1/gti_missions_challenges?select=*&order=created_at.desc');
  let proofs=[];try{proofs=await rpc('gti_missions_admin_recent_proofs')||[]}catch{}
  const proofCards=await Promise.all(proofs.map(async p=>({...p,url:await signedCheckin(p.photo_path,300)})));
  const today=new Date().toISOString().slice(0,10);
  app.innerHTML=shell(`<header class="page-head"><div><small>ÁREA RESTRITA</small><h1>🛡️ Administração</h1><p>Somente contas administrativas do backend criam missões. Não existe senha/código de ADM exposto no aplicativo.</p></div></header><section class="admin-panel"><form id="challengeForm" class="settings-card"><h2>Criar nova missão</h2><div class="field-pair"><label>Nome<input id="ctitle" maxlength="80" required placeholder="Ex.: Study Streak"></label><label>Ícone / emoji<input id="cicon" maxlength="16" value="🎯" required></label></div><label>Descrição<textarea id="cdesc" maxlength="500" placeholder="Explique a missão e o comportamento esperado."></textarea></label><div class="field-pair"><label>Tipo<select id="cmode"><option value="checkin">Check-in diário</option><option value="quantity">Meta por quantidade</option></select></label><label>Dias para fechar a semana<select id="cweek">${[1,2,3,4,5,6,7].map(x=>`<option value="${x}" ${x===7?'selected':''}>${x} dias</option>`).join('')}</select></label></div><div id="quantityFields" class="field-pair hidden"><label>Meta diária<input id="ctarget" type="number" min="0.01" step="0.01" value="1"></label><label>Unidade<input id="cunit" maxlength="30" value="unidades" placeholder="páginas, minutos, passos..."></label></div><label class="check-row admin-photo-option"><input id="crequires" type="checkbox" checked><span><b>Exigir foto tirada na hora</b><small>O app abre a câmera, não o seletor de galeria. A prova é privada e apagada automaticamente após 24h.</small></span></label><div class="field-pair"><label>XP por dia concluído<input id="cdailyxp" type="number" min="1" max="100" value="25"></label><label>Bônus ao fechar a semana<input id="cweekxp" type="number" min="0" max="250" value="100"></label></div><div class="field-pair"><label>Início<input id="cstart" type="date" value="${today}" required></label><label>Fim opcional<input id="cend" type="date"></label></div><button class="primary">Publicar missão</button><div id="adminMsg"></div></form><h2 class="section-title">Missões criadas</h2><section class="admin-list">${rows?.length?rows.map(c=>`<article><div><strong>${esc(c.icon)} ${esc(c.title)}</strong><small>${c.mode==='checkin'?'check-in':`${fmt(c.daily_target)} ${esc(c.unit_label)}`} • ${c.weekly_target_days}d/sem • +${c.xp_per_day} XP/dia ${c.requires_photo?'• 📸 prova 24h':''}</small></div><button class="${c.is_active?'danger':'secondary'}" data-toggle="${c.id}" data-active="${c.is_active}">${c.is_active?'Desativar':'Ativar'}</button></article>`).join(''):'<div class="empty">Nenhuma missão customizada criada ainda.</div>'}</section><h2 class="section-title">📸 Checks com foto • últimas 24h</h2><p class="field-help">As imagens abaixo são temporárias. Depois do vencimento o arquivo é removido automaticamente; o registro do check permanece.</p><section class="proof-grid">${proofCards.length?proofCards.map(p=>`<article class="proof-card">${p.url?`<img src="${esc(p.url)}" alt="Prova de check">`:'<div class="proof-missing">foto indisponível</div>'}<div><b>${esc(p.icon||'🎯')} ${esc(p.challenge_title)}</b><span>${esc(p.display_name)} • @${esc(p.username)}</span><small>${new Date(p.completed_at).toLocaleString('pt-BR')} • expira ${new Date(p.photo_expires_at).toLocaleString('pt-BR')}</small></div></article>`).join(''):'<div class="empty">Nenhuma foto de check ativa agora.</div>'}</section></section>`,'app');
  bindNav();
  const mode=document.getElementById('cmode'),qf=document.getElementById('quantityFields');mode.onchange=()=>qf.classList.toggle('hidden',mode.value!=='quantity');
  document.getElementById('challengeForm').onsubmit=async e=>{e.preventDefault();const m=document.getElementById('adminMsg');try{await rpc('gti_missions_admin_create_challenge',{p_title:document.getElementById('ctitle').value.trim(),p_description:document.getElementById('cdesc').value.trim(),p_icon:document.getElementById('cicon').value.trim(),p_mode:mode.value,p_unit_label:document.getElementById('cunit').value.trim(),p_daily_target:mode.value==='quantity'?+document.getElementById('ctarget').value:null,p_weekly_target_days:+document.getElementById('cweek').value,p_xp_per_day:+document.getElementById('cdailyxp').value,p_weekly_bonus_xp:+document.getElementById('cweekxp').value,p_starts_on:document.getElementById('cstart').value,p_ends_on:document.getElementById('cend').value||null,p_requires_photo:document.getElementById('crequires').checked});m.innerHTML='<div class="success">Missão publicada para a comunidade. 🎯</div>';setTimeout(()=>renderAdmin(),450)}catch(err){m.innerHTML=`<div class="notice">${esc(friendly(err))}</div>`}};
  document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=async()=>{try{await rpc('gti_missions_admin_toggle_challenge',{p_challenge_id:b.dataset.toggle,p_active:b.dataset.active!=='true'});renderAdmin()}catch(err){alert(friendly(err))}})
}

function renderTerms(){app.innerHTML=`<main class="legal-page"><article class="legal-card"><button class="back-link" data-nav="home">← GTI Missions</button><div class="brand-pill">VERSÃO 1.2 • 09/09/2026</div><h1>Termos de Uso</h1><p>O GTI Missions é uma experiência gamificada da Galera do TI para incentivar consistência em hábitos e desafios da comunidade.</p><h2>1. Gamificação</h2><p>XP, níveis, ofensivas, selos e rankings são recreativos. AquaXP exige 7/7 dias para o selo semanal; Tech Rat permite meta de 3 a 7 dias.</p><h2>2. Saúde</h2><p>IMC e referência de hidratação são estimativas informativas. Não são diagnóstico nem prescrição. Condições de saúde, gestação, medicamentos e necessidades individuais podem exigir orientação profissional.</p><h2>3. Desafios da administração</h2><p>Somente contas administrativas autorizadas no backend podem publicar desafios. Alguns desafios podem exigir uma foto tirada na hora como confirmação do check.</p><h2>4. Foto de check</h2><p>O AquaXP, o Tech Rat e os desafios configurados com prova solicitam acesso à câmera somente após ação do usuário. A captura valida o registro, não pode ser escolhida da galeria e fica disponível por somente 24 horas.</p><h2>5. Integridade</h2><p>Manipulação, automação ou exploração de falhas pode resultar em correção de XP ou restrição.</p><h2>6. League</h2><p>Nome/apelido, @username, foto de perfil, posição e XP mensal podem ser vistos por participantes autenticados.</p><div class="legal-links"><button class="secondary" data-nav="privacy">Privacidade</button><button class="primary" data-nav="login">Entrar</button></div></article></main>`;bindNav()}
function renderPrivacy(){app.innerHTML=`<main class="legal-page"><article class="legal-card"><button class="back-link" data-nav="home">← GTI Missions</button><div class="brand-pill">VERSÃO 1.2 • 09/09/2026</div><h1>Política de Privacidade</h1><p>Para operar o GTI Missions podemos tratar e-mail/credencial, nome/apelido, @username, foto de perfil, altura, peso, metas, registros de água/exercício/desafios, XP, selos e, quando exigido pela missão, foto temporária de check.</p><h2>Altura, peso e IMC</h2><p>Altura e peso são opcionais e usados para exibir IMC estimado e uma referência aproximada de hidratação. Esses dados não aparecem na League.</p><h2>Foto de perfil</h2><p>A foto de perfil é opcional, fica em bucket privado e é exibida por URL temporária assinada para participantes autenticados.</p><h2>Foto temporária de check</h2><p>No AquaXP, no Tech Rat e em desafios configurados com prova, a imagem é capturada diretamente pela câmera do dispositivo. O app não oferece seletor de galeria nesse fluxo. A foto fica em bucket privado, pode ser consultada pela própria pessoa e pela administração para conferência, e é apagada automaticamente após 24 horas. O registro textual do check e o XP permanecem.</p><h2>O que aparece na League</h2><p>Nome/apelido, @username, foto de perfil, XP mensal e posição. E-mail, altura, peso, IMC, metas, registros detalhados e fotos de check não aparecem na League.</p><h2>Administração</h2><p>A criação de desafios é protegida por papel administrativo no banco de dados. Não existe senha administrativa compartilhada embutida no frontend.</p><h2>Exclusão</h2><p>A opção de exclusão remove os dados do GTI Missions associados ao perfil conforme as regras do serviço. Fotos temporárias de check também estão sujeitas à retenção máxima de 24 horas.</p><div class="legal-links"><button class="secondary" data-nav="terms">Termos</button><button class="primary" data-nav="login">Entrar</button></div></article></main>`;bindNav()}

if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{});
render();